  for (int b = 0; b <= 255; b += 5) {  // fade in
    analogWrite(pin, b);
    delay(4);
  }
  for (int b = 255; b >= 0; b -= 3) {  // fade out slower
    analogWrite(pin, b);
    delay(6);
  }
}

