const int R = 9, G = 10, B = 11, BUTTON = 2;
int mode = 0;
const int MODES = 5;
bool lastButton = HIGH;

void color(int r, int g, int b) {
  analogWrite(R, r);
  analogWrite(G, g);
  analogWrite(B, b);
}

void setup() {
  pinMode(R, OUTPUT);
  pinMode(G, OUTPUT);
  pinMode(B, OUTPUT);
  pinMode(BUTTON, INPUT_PULLUP);
}

void loop() {
  bool button = digitalRead(BUTTON);
  if (button == LOW && lastButton == HIGH) {  // just pressed
    mode = (mode + 1) % MODES;
    delay(40);  // tiny debounce
  }
  lastButton = button;

  unsigned long t = millis();
  switch (mode) {
    case 0: color(255, 90, 10); break;   // warm
    case 1: color(40, 120, 255); break;  // cool
    case 2:                              // party: new color every 150 ms
      if ((t / 150) % 3 == 0) color(255, 0, 0);
      else if ((t / 150) % 3 == 1) color(0, 255, 0);
      else color(0, 0, 255);
      break;
    case 3: {                            // slow rainbow using sine waves
      float s = t / 1000.0;
      color((sin(s) + 1) * 127, (sin(s + 2.1) + 1) * 127, (sin(s + 4.2) + 1) * 127);
      break;
    }
    default: color(0, 0, 0); break;      // off
  }
}

const int PIR_PIN = 2;
const int LIGHT_PIN = 9;
const unsigned long STAY_ON_MS = 20000;  // 20 seconds

unsigned long lastMotionTime = 0;
bool lightOn = false;

void setup() {
  pinMode(PIR_PIN, INPUT);
  pinMode(LIGHT_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  // Every time we see motion, restart the timer.
  if (digitalRead(PIR_PIN) == HIGH) {
    lastMotionTime = millis();
    if (!lightOn) {
      lightOn = true;
      digitalWrite(LIGHT_PIN, HIGH);
      Serial.println("Light ON");
    }
  }

  // millis() - start is the safe way to measure time, even when millis wraps around.
  if (lightOn && millis() - lastMotionTime >= STAY_ON_MS) {
    lightOn = false;
    digitalWrite(LIGHT_PIN, LOW);
    Serial.println("No motion for a while, light off");
  }
}

