int pan = 90;
int tilt = 90;

// Turns a joystick reading into a speed from -3 to 3, with a dead zone in the middle.
int stickSpeed(int reading) {
  int offset = reading - 512;
  if (abs(offset) < 80) return 0;
  return map(offset, -512, 511, -3, 3);
}

void setup() {
  panServo.attach(9);
  tiltServo.attach(10);
  pinMode(2, INPUT_PULLUP);
}

void loop() {
  pan = constrain(pan + stickSpeed(analogRead(A0)), 0, 180);
  tilt = constrain(tilt + stickSpeed(analogRead(A1)), 20, 160);

  if (digitalRead(2) == LOW) {  // button pressed: go back to the middle
    pan = 90;
    tilt = 90;
  }

  panServo.write(pan);
  tiltServo.write(tilt);
  delay(15);
}

const int TRIG_PIN = 9;
const int ECHO_PIN = 10;
const int BUZZER_PIN = 8;

long readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);  // a 10 microsecond ping
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  unsigned long duration = pulseIn(ECHO_PIN, HIGH, 30000UL);  // give up after 30 ms
  if (duration == 0) return 999;  // nothing in range
  return duration / 58;           // sound: about 58 microseconds per cm there and back
}

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
}

void loop() {
  long cm = readDistanceCm();

  if (cm < 5) {
    tone(BUZZER_PIN, 2000);  // super close: one long beep
    delay(100);
  } else if (cm < 60) {
    noTone(BUZZER_PIN);
    // Closer = shorter gap between beeps (5 cm -> 25 ms, 60 cm -> 600 ms).
    int gap = map(cm, 5, 60, 25, 600);
    tone(BUZZER_PIN, 2000, 60);
    delay(60 + gap);
  } else {
    noTone(BUZZER_PIN);  // far away: quiet
    delay(100);
  }
}

const int PIR_PIN = 2;
const int LED_PIN = 13;
const int BUZZER_PIN = 8;

void setup() {
