  digitalWrite(SENSOR_POWER, HIGH);  // power on only when reading: the sensor lasts longer
  delay(10);
  int raw = analogRead(SENSOR_PIN);
  digitalWrite(SENSOR_POWER, LOW);
  int percent = map(raw, DRY_VALUE, WET_VALUE, 0, 100);
