const int RELAY_PIN = 7;
const int BUTTON_PIN = 2;
bool relayOn = false;
bool lastButton = HIGH;
unsigned long lastChange = 0;

void setup() {
  pinMode(RELAY_PIN, OUTPUT);
  pinMode(LED_BUILTIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
}

void loop() {
  bool button = digitalRead(BUTTON_PIN);

  // Only count a press if 50 ms have passed since the last change (debounce).
  if (button != lastButton && millis() - lastChange > 50) {
    lastChange = millis();
    if (button == LOW) {  // pressed down
      relayOn = !relayOn;
      digitalWrite(RELAY_PIN, relayOn ? HIGH : LOW);
      digitalWrite(LED_BUILTIN, relayOn ? HIGH : LOW);
    }
    lastButton = button;
  }
}

#include <SPI.h>
#include <MFRC522.h>

const int SS_PIN = 10;
const int RST_PIN = 9;
MFRC522 rfid(SS_PIN, RST_PIN);

void setup() {
  Serial.begin(9600);
  SPI.begin();
  rfid.PCD_Init();
  Serial.println("Hold a card near the reader...");
}

void loop() {
  // Wait for a new card and read its ID.
  if (!rfid.PICC_IsNewCardPresent()) return;
  if (!rfid.PICC_ReadCardSerial()) return;

  Serial.print("Card ID:");
  for (byte i = 0; i < rfid.uid.size; i++) {
    Serial.print(rfid.uid.uidByte[i] < 0x10 ? " 0" : " ");  // add a leading 0
    Serial.print(rfid.uid.uidByte[i], HEX);
  }
  Serial.println();

  rfid.PICC_HaltA();  // tell the card we are done
  rfid.PCD_StopCrypto1();
}

#include <SPI.h>
#include <MFRC522.h>
#include <Servo.h>

MFRC522 rfid(10, 9);
Servo lock;
const int GREEN_LED = 4;
const int RED_LED = 5;

// Change these 4 numbers to your card's ID.
const byte MY_CARD[4] = {0xDE, 0xAD, 0xBE, 0xEF};

bool isMyCard() {
  if (rfid.uid.size != 4) return false;
  for (byte i = 0; i < 4; i++) {
    if (rfid.uid.uidByte[i] != MY_CARD[i]) return false;
  }
  return true;
}

void setup() {
  SPI.begin();
  rfid.PCD_Init();
  lock.attach(6);
  lock.write(0);  // 0 = locked
  pinMode(GREEN_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);
}

void loop() {
  if (!rfid.PICC_IsNewCardPresent() || !rfid.PICC_ReadCardSerial()) return;

  if (isMyCard()) {
    digitalWrite(GREEN_LED, HIGH);
    lock.write(90);  // unlock
    delay(3000);
    lock.write(0);   // lock again
    digitalWrite(GREEN_LED, LOW);
  } else {
    for (int i = 0; i < 3; i++) {
      digitalWrite(RED_LED, HIGH);
      delay(150);
      digitalWrite(RED_LED, LOW);
      delay(150);
    }
  }
  rfid.PICC_HaltA();
  rfid.PCD_StopCrypto1();
}

const int RED_PIN = 9;
const int GREEN_PIN = 10;
const int BLUE_PIN = 11;

// For a common ANODE LED (long leg to 5V), change this to true.
const bool COMMON_ANODE = false;

void setColor(int red, int green, int blue) {
  if (COMMON_ANODE) {  // anode LEDs are upside down: 255 means off
    red = 255 - red;
    green = 255 - green;
    blue = 255 - blue;
  }
  analogWrite(RED_PIN, red);
  analogWrite(GREEN_PIN, green);
  analogWrite(BLUE_PIN, blue);
}

void setup() {
  pinMode(RED_PIN, OUTPUT);
  pinMode(GREEN_PIN, OUTPUT);
  pinMode(BLUE_PIN, OUTPUT);
}

void loop() {
  setColor(255, 0, 0);     delay(700);  // red
  setColor(0, 255, 0);     delay(700);  // green
  setColor(0, 0, 255);     delay(700);  // blue
  setColor(255, 255, 0);   delay(700);  // yellow = red + green
  setColor(128, 0, 255);   delay(700);  // purple
  setColor(0, 255, 255);   delay(700);  // cyan = green + blue
  setColor(255, 80, 0);    delay(700);  // orange
  setColor(255, 255, 255); delay(700);  // white = everything
}

const int RED_PIN = 9, GREEN_PIN = 10, BLUE_PIN = 11;

// Turns a position on the color wheel (0 to 767) into red, green and blue.
void wheel(int pos) {
  int r, g, b;
  if (pos < 256) {         // red -> green
    r = 255 - pos; g = pos; b = 0;
  } else if (pos < 512) {  // green -> blue
    pos -= 256;
    r = 0; g = 255 - pos; b = pos;
  } else {                 // blue -> red
    pos -= 512;
    r = pos; g = 0; b = 255 - pos;
  }
  analogWrite(RED_PIN, r);
  analogWrite(GREEN_PIN, g);
  analogWrite(BLUE_PIN, b);
}

void setup() {
  pinMode(RED_PIN, OUTPUT);
  pinMode(GREEN_PIN, OUTPUT);
  pinMode(BLUE_PIN, OUTPUT);
}

void loop() {
  for (int pos = 0; pos < 768; pos++) {
    wheel(pos);
    delay(8);
  }
}

