}

const int CLK_PIN = 2;  // interrupt pin
const int DT_PIN = 3;
const int SW_PIN = 4;

volatile long position = 0;  // volatile: changed inside an interrupt
long lastPrinted = -1;

// Runs by itself every time CLK falls.
void onTurn() {
  // If DT is different from CLK, we turned clockwise.
  if (digitalRead(DT_PIN) != digitalRead(CLK_PIN)) {
    position++;
  } else {
    position--;
  }
}

void setup() {
  pinMode(CLK_PIN, INPUT_PULLUP);
  pinMode(DT_PIN, INPUT_PULLUP);
  pinMode(SW_PIN, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(CLK_PIN), onTurn, FALLING);
  Serial.begin(9600);
}

void loop() {
  // Copy the number with interrupts paused so it does not change halfway.
  noInterrupts();
  long now = position;
  interrupts();

  if (now != lastPrinted) {
    Serial.print("Position: ");
    Serial.println(now);
    lastPrinted = now;
  }

  if (digitalRead(SW_PIN) == LOW) {
    noInterrupts();
    position = 0;
    interrupts();
    delay(250);
  }
}

const int PIEZO_PIN = A0;
const int LED_PIN = 13;
const int KNOCK_THRESHOLD = 60;     // raise this if it triggers by itself
const unsigned long WINDOW_MS = 2000;

int knocks = 0;
unsigned long firstKnock = 0;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int level = analogRead(PIEZO_PIN);
  if (level > KNOCK_THRESHOLD) {
    if (knocks == 0) firstKnock = millis();
    knocks++;
    Serial.print("Knock ");
    Serial.print(knocks);
    Serial.print(" (strength ");
    Serial.print(level);
    Serial.println(")");
    delay(120);  // skip the wobble of the same knock
  }

  if (knocks >= 3) {
    Serial.println("Secret knock accepted!");
    digitalWrite(LED_PIN, HIGH);
    delay(2000);
    digitalWrite(LED_PIN, LOW);
    knocks = 0;
  }

  // Too slow: start over.
  if (knocks > 0 && millis() - firstKnock > WINDOW_MS) {
    knocks = 0;
    Serial.println("Too slow, try again.");
  }
}

#include <Servo.h>

Servo door;
const int BUTTON_PIN = 2;
const int CLOSED = 10;
const int OPEN = 100;
int angle = CLOSED;
bool isOpen = false;

void moveSlowly(int target) {
  while (angle != target) {
    angle += (target > angle) ? 1 : -1;
    door.write(angle);
    delay(12);  // smaller = faster door
  }
}

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  door.attach(9);
  door.write(angle);
}

void loop() {
  if (digitalRead(BUTTON_PIN) == LOW) {
    isOpen = !isOpen;
    moveSlowly(isOpen ? OPEN : CLOSED);
    while (digitalRead(BUTTON_PIN) == LOW) delay(10);  // wait for release
    delay(50);
  }
}

