// A struct groups related data together.
struct Score {
  std::string name;
  int points;
};

void printTop(const std::vector<Score> &scores, std::size_t howMany) {
  std::cout << "\n=== HIGH SCORES ===\n";
  for (std::size_t i = 0; i < scores.size() && i < howMany; i++) {
    std::cout << (i + 1) << ". " << scores[i].name << " - " << scores[i].points << "\n";
  }
}

int main() {
  std::vector<Score> scores = {
      {"Ava", 1200}, {"Leo", 950}, {"Mia", 1500}, {"Sam", 700}, {"Zoe", 1100}};

  // Ask for the player's name.
  std::cout << "Your name: ";
  std::string name;
  if (!std::getline(std::cin, name)) return 0;
  if (name.empty()) name = "Player";

  // Ask for a score until it's a real number.
  int points = 0;
  while (true) {
    std::cout << "Your score: ";
    std::string line;
    if (!std::getline(std::cin, line)) return 0;
    std::istringstream in(line);
    char extra;
    if (in >> points && !(in >> extra) && points >= 0) break;
    std::cout << "Please type a whole number (0 or more).\n";
  }
  scores.push_back({name, points});

  // Sort biggest first. The little function says how to compare two scores.
  std::sort(scores.begin(), scores.end(), [](const Score &a, const Score &b) {
    return a.points > b.points;
  });

  printTop(scores, 5);

  // Find where the player ended up.
  for (std::size_t i = 0; i < scores.size(); i++) {
    if (scores[i].name == name && scores[i].points == points) {
      std::cout << "\nYou placed #" << (i + 1) << "!";
      if (i < 5) std::cout << " You made the top 5!";
      std::cout << "\n";
      break;
    }
  }
  return 0;
}

#include <iostream>

int main() {
  // The classic first program.
  std::cout << "Hello, world!\n\n";

  // A for loop: start at 1, keep going while i <= 5, add 1 each time.
  std::cout << "Counting up: ";
  for (int i = 1; i <= 5; i++) {
    std::cout << i << " ";
  }
  std::cout << "\n";

  // A while loop: keep going while the condition is true.
  std::cout << "Doubling: ";
  int number = 1;
  while (number < 200) {
    std::cout << number << " ";
    number *= 2;
  }
  std::cout << "\n\n";

  // If / else if / else with FizzBuzz:
  // multiples of 3 say Fizz, of 5 say Buzz, of both say FizzBuzz.
  for (int i = 1; i <= 20; i++) {
    if (i % 15 == 0) {
      std::cout << "FizzBuzz\n";
    } else if (i % 3 == 0) {
      std::cout << "Fizz\n";
    } else if (i % 5 == 0) {
      std::cout << "Buzz\n";
    } else {
      std::cout << i << "\n";
    }
  }

  // A loop inside a loop makes a times table.
  std::cout << "\nTimes table:\n";
  for (int row = 1; row <= 5; row++) {
    for (int col = 1; col <= 5; col++) {
      int value = row * col;
      if (value < 10) std::cout << " ";  // line up the columns
      std::cout << value << " ";
    }
    std::cout << "\n";
  }
  return 0;
}

