import functools
import time


def timer(func):
    """Measures how long the function takes."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        print(f"  {func.__name__} took {time.perf_counter() - start:.4f} seconds")
        return result
    return wrapper


def announce(func):
    """Prints a message before and after the function runs."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f"Starting {func.__name__}...")
        result = func(*args, **kwargs)
        print(f"Finished {func.__name__}!")
        return result
    return wrapper


# Putting @timer on top is the same as writing: add_numbers = timer(add_numbers)
@timer
def add_numbers(limit):
    return sum(range(limit))


@announce
@timer
def make_greeting(name):
    time.sleep(0.2)
    return f"Hey {name}!"


print("Sum:", add_numbers(1_000_000))
print(make_greeting("Storm"))

import time
from functools import lru_cache


def slow_fib(n):
    # Calls itself twice each time, so it repeats a LOT of work.
    if n < 2:
        return n
    return slow_fib(n - 1) + slow_fib(n - 2)


@lru_cache(maxsize=None)
def fast_fib(n):
    # Same code, but lru_cache remembers every answer it has already worked out.
    if n < 2:
        return n
    return fast_fib(n - 1) + fast_fib(n - 2)


