# Checking brackets is a classic stack problem
def balanced(code):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in code:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

for code in ["print((1 + 2) * [3])", "{[}]", "((("]:
    print(code, "->", "balanced" if balanced(code) else "NOT balanced")

