import random

SIZE = 4
grid = [[0] * SIZE for _ in range(SIZE)]


def add_tile():
    empty = [(r, c) for r in range(SIZE) for c in range(SIZE) if grid[r][c] == 0]
    if empty:
        r, c = random.choice(empty)
        grid[r][c] = 4 if random.random() < 0.1 else 2


def slide_row_left(row):
    """Slide one row to the left and merge pairs. Returns the new row and points scored."""
    tiles = [n for n in row if n]
    merged, points, i = [], 0, 0
    while i < len(tiles):
        if i + 1 < len(tiles) and tiles[i] == tiles[i + 1]:
            merged.append(tiles[i] * 2)
            points += tiles[i] * 2
            i += 2
        else:
            merged.append(tiles[i])
            i += 1
    return merged + [0] * (SIZE - len(merged)), points


def move(direction):
    """Every direction is 'left' after flipping or turning the grid."""
    global grid
    rotated = grid
    turns = {"a": 0, "w": 1, "d": 2, "s": 3}[direction]
    for _ in range(turns):  # turn the grid counter-clockwise
        rotated = [list(row) for row in zip(*rotated)][::-1]
    results = [slide_row_left(row) for row in rotated]
    new = [row for row, _ in results]
    for _ in range((4 - turns) % 4):  # turn it back
        new = [list(row) for row in zip(*new)][::-1]
    changed = new != grid
    grid = new
    return changed, sum(p for _, p in results)


def can_move():
    for r in range(SIZE):
        for c in range(SIZE):
            if grid[r][c] == 0:
                return True
            if c + 1 < SIZE and grid[r][c] == grid[r][c + 1]:
                return True
            if r + 1 < SIZE and grid[r][c] == grid[r + 1][c]:
                return True
    return False


score = 0
add_tile()
add_tile()
while True:
    print(f"\nScore: {score}")
    for row in grid:
        print("".join(f"{n or '.':>6}" for n in row))
    if any(2048 in row for row in grid):
        print("You made 2048! You win!")
        break
    if not can_move():
        print("No moves left. Game over!")
        break
    key = input("Move with w/a/s/d (q to quit): ").strip().lower()
    if key == "q":
        break
    if key in ("w", "a", "s", "d"):
        changed, points = move(key)
        if changed:
            score += points
            add_tile()

ROWS, COLS = 6, 7
board = [["." for _ in range(COLS)] for _ in range(ROWS)]


def draw():
    print()
    for row in board:
        print(" ".join(row))
    print(" ".join(str(c + 1) for c in range(COLS)))


def drop(col, disc):
    """Put the disc in the lowest empty spot of the column. Returns the row, or None if full."""
    for row in range(ROWS - 1, -1, -1):
        if board[row][col] == ".":
            board[row][col] = disc
            return row
    return None


def wins(row, col, disc):
    # Check 4 directions: across, down, and both diagonals.
    for dr, dc in [(0, 1), (1, 0), (1, 1), (1, -1)]:
        count = 1
        for sign in (1, -1):  # look both ways from the new disc
            r, c = row + dr * sign, col + dc * sign
            while 0 <= r < ROWS and 0 <= c < COLS and board[r][c] == disc:
                count += 1
                r += dr * sign
                c += dc * sign
        if count >= 4:
            return True
    return False


disc = "X"
for turn in range(ROWS * COLS):
    draw()
    text = input(f"Player {disc}, pick a column (1-{COLS}): ").strip()
    while not (text.isdigit() and 1 <= int(text) <= COLS and board[0][int(text) - 1] == "."):
        text = input("That column can't be used. Pick another: ").strip()
    col = int(text) - 1
    row = drop(col, disc)
    if wins(row, col, disc):
        draw()
        print(f"Player {disc} connects four and wins!")
        break
    disc = "O" if disc == "X" else "X"
else:
    draw()
    print("The board is full. It's a draw!")

